finalize_it:
    if (iRet != RS_RET_OK) {
        LogError(0, NO_ERRCODE, "imtcp: error %d trying to add listener", iRet);
        if (pOurTcpsrv != NULL) {
            tcpsrv.SetUsrP(pOurTcpsrv, NULL);
