/* This function is called when a new listener instace shall be added to
 * the current config object via the legacy config system. It just shuffles
 * all parameters to the listener in-memory instance.
 * rgerhards, 2011-05-04
 */
static rsRetVal addInstance(void __attribute__((unused)) * pVal, uchar *pNewVal) {
    instanceConf_t *inst;
    DEFiRet;

    CHKiRet(createInstance(&inst));
    CHKmalloc(inst->pszBindPort = ustrdup((pNewVal == NULL || *pNewVal == '\0') ? (uchar *)"514" : pNewVal));
    if ((cs.pszBindAddr == NULL) || (cs.pszBindAddr[0] == '\0')) {
        inst->pszBindAddr = NULL;
    } else {
        CHKmalloc(inst->pszBindAddr = ustrdup(cs.pszBindAddr));
    }
    if ((cs.pszBindDevice == NULL) || (cs.pszBindDevice[0] == '\0')) {
        inst->pszBindDevice = NULL;
    } else {

uchar *bindName;
uchar *port;
uchar dispname[64], inpnameBuf[128];
uchar *inputname;

/* check which address to bind to. We could do this more compact, but have not
 * done so in order to make the code more readable. -- rgerhards, 2007-12-27
 */
if (inst->pszBindAddr == NULL)
    bindAddr = NULL;
else if (inst->pszBindAddr[0] == '*' && inst->pszBindAddr[1] == '\0')
    bindAddr = NULL;
else
    bindAddr = inst->pszBindAddr;
bindName = (bindAddr == NULL) ? (uchar *)"*" : bindAddr;
port = (inst->pszBindPort == NULL || *inst->pszBindPort == '\0') ? (uchar *)"514" : inst->pszBindPort;

DBGPRINTF("Trying to open syslog UDP ports at %s:%s.\n", bindName, inst->pszBindPort);

newSocks = net.create_udp_socket(bindAddr, port, 1, inst->rcvbuf, 0, inst->ipfreebind, inst->pszBindDevice);
if (newSocks != NULL) {
    if (inst->pszLstnPortFileName != NULL && newSocks[0] != 1) {
        LogError(0, RS_RET_INVALID_PARAMS,
                 "imudp: listenPortFileName requires exactly one bound "
                 "socket, got %d; set address to a single local address",
                 newSocks[0]);
        ABORT_FINALIZE(RS_RET_INVALID_PARAMS);
    }
    /* we now need to add the new sockets to the existing set */
    /* ready to copy */
    for (iSrc = 1; iSrc <= newSocks[0]; ++iSrc) {
        union {
            struct sockaddr_storage storage;
            struct sockaddr_in ipv4;
            struct sockaddr_in6 ipv6;
        } sa;
        socklen_t salen = sizeof(sa.storage);
        const char *suffix;
        unsigned listenPort = 0;
        CHKmalloc(newlcnfinfo = (struct lstn_s *)calloc(1, sizeof(struct lstn_s)));
        newlcnfinfo->next = NULL;
        newlcnfinfo->sock = newSocks[iSrc];
        newlcnfinfo->pRuleset = inst->pBindRuleset;
        newlcnfinfo->dfltTZ = inst->dfltTZ;
        newlcnfinfo->ratelimiter = NULL;
        if (inst->bAllowedSendersSet) {
            newlcnfinfo->pAllowedSenderRoot = inst->pAllowedSendersRoot;
            newlcnfinfo->bUseLegacyAllowedSender = 0;
        } else if (runModConf->bAllowedSendersSet) {
            newlcnfinfo->pAllowedSenderRoot = runModConf->pAllowedSendersRoot;
            newlcnfinfo->bUseLegacyAllowedSender = 0;
        } else {
            newlcnfinfo->pAllowedSenderRoot = NULL;
            newlcnfinfo->bUseLegacyAllowedSender = 1;
        }
        /* query socket IPv4 vs IPv6 */
        sa.storage.ss_family = 0; /* just to keep CLANG static analyzer happy! */
        if (getsockname(newlcnfinfo->sock, (struct sockaddr *)&sa.storage, &salen) != 0) {
            suffix = "error_getting_AF...";
        } else {
            if (sa.storage.ss_family == AF_INET) {
                suffix = "IPv4";
                listenPort = ntohs(sa.ipv4.sin_port);
            } else if (sa.storage.ss_family == AF_INET6) {
                suffix = "IPv6";
                listenPort = ntohs(sa.ipv6.sin6_port);
            } else {
                suffix = "AF_unknown";
            }
        }
        if (inst->inputname == NULL) {
            inputname = (uchar *)"imudp";
        } else {
            inputname = inst->inputname;
        }
        snprintf((char *)dispname, sizeof(dispname), "%s(%s/%s/%s)", inputname, bindName, port, suffix);
        dispname[sizeof(dispname) - 1] = '\0'; /* just to be on the save side... */
        if (inst->pszRatelimitName != NULL) {
            CHKiRet(ratelimitNewFromConfig(&newlcnfinfo->ratelimiter, runModConf->pConf,
                                           (char *)inst->pszRatelimitName, (char *)dispname, NULL));
            /* named ratelimiters use the shared registry configuration exclusively.
             * Per-instance interval/burst parameters are ignored/prohibited when ratelimit.name is set.
             */
        } else {
            CHKiRet(ratelimitNew(&newlcnfinfo->ratelimiter, (char *)dispname, NULL));
            ratelimitSetLinuxLike(newlcnfinfo->ratelimiter,
                                  (inst->ratelimitInterval == -1) ? 0 : (unsigned)inst->ratelimitInterval,
                                  (inst->ratelimitBurst == -1) ? 0 : (unsigned)inst->ratelimitBurst);

                CHKiRet(writeListenPortFile(inst->pszLstnPortFileName, listenPort));
            }
            /* link to list. Order must be preserved to take care for
             * conflicting matches.
             */
            if (lcnfRoot == NULL) lcnfRoot = newlcnfinfo;
            if (lcnfLast == NULL)
                lcnfLast = newlcnfinfo;
            else {
                lcnfLast->next = newlcnfinfo;
                lcnfLast = newlcnfinfo;
            }
        }
    } else {
        LogError(0, NO_ERRCODE,
                 "imudp: Could not create udp listener,"
                 " ignoring port %s bind-address %s.",
                 port, bindAddr);
    }

finalize_it:
    if (iRet != RS_RET_OK) {
        if (newlcnfinfo != NULL) {
            if (newlcnfinfo->ratelimiter != NULL) ratelimitDestruct(newlcnfinfo->ratelimiter);
            if (newlcnfinfo->pInputName != NULL) prop.Destruct(&newlcnfinfo->pInputName);
            if (newlcnfinfo->stats != NULL) statsobj.Destruct(&newlcnfinfo->stats);
            free(newlcnfinfo);
        }
        /* close the rest of the open sockets as there's
           nowhere to put them */
        if (newSocks != NULL) {
            for (; iSrc <= newSocks[0]; iSrc++) {
                close(newSocks[iSrc]);
            }
        }
    }

    free(newSocks);
    RETiRet;
}


