                              socklen_t socklen,
                              multi_submit_t *multiSub) {
    DEFiRet;
    smsg_t *pMsg = NULL;

    if (lenRcvBuf == 0) FINALIZE; /* this looks a bit strange, but practice shows it happens... */

    /* if we reach this point, we had a good receive and can process the packet received */
    /* check if we have a different sender than before, if so, we need to query some new values */
    if (bDoACLCheck) {
        const socklen_t cmpSocklen = sizeof(struct sockaddr_storage);
        if (*ppLstnPrev != lstn || net.CmpHost(frominet, frominetPrev, cmpSocklen) != 0) {
            memcpy(frominetPrev, frominet, cmpSocklen); /* update cache indicator */
            *ppLstnPrev = lstn;
            /* Here we check if a host is permitted to send us syslog messages. If it isn't,
             * we do not further process the message but log a warning (if we are
             * configured to do this). However, if the check would require name resolution,
             * it is postponed to the main queue. See also my blog post at
             * http://blog.gerhards.net/2009/11/acls-imudp-and-accepting-messages.html
             * rgerhards, 2009-11-16
             */
            if (lstn->bUseLegacyAllowedSender) {
                *pbIsPermitted = net.isAllowedSender2((uchar *)"UDP", (struct sockaddr *)frominet, "", 0);
            } else {
                *pbIsPermitted = net.isAllowedSenderList(lstn->pAllowedSenderRoot, (struct sockaddr *)frominet, "", 0);
            }

            if (*pbIsPermitted == 0) {
                DBGPRINTF("msg is not from an allowed sender\n");
                STATSCOUNTER_INC(lstn->ctrDisallowed, lstn->mutCtrDisallowed);
                if (glbl.GetOptionDisallowWarning(runModConf->pConf)) {
                    LogError(0, NO_ERRCODE, "imudp: UDP message from disallowed sender discarded");
                }
            }
        }
    } else {
        *pbIsPermitted = 1; /* no check -> everything permitted */
    }

    DBGPRINTF("recv(%d,%d),acl:%d,msg:%.*s\n", lstn->sock, (int)lenRcvBuf, *pbIsPermitted, (int)lenRcvBuf, rcvBuf);

    if (*pbIsPermitted != 0) {
        /* we now create our own message object and submit it to the queue */
        CHKiRet(msgConstructWithTime(&pMsg, stTime, ttGenTime));
        MsgSetRawMsg(pMsg, (char *)rcvBuf, lenRcvBuf);
        MsgSetInputName(pMsg, lstn->pInputName);
        MsgSetRuleset(pMsg, lstn->pRuleset);
        MsgSetFlowControlType(pMsg, eFLOWCTL_NO_DELAY);
        if (lstn->dfltTZ != NULL) MsgSetDfltTZ(pMsg, (char *)lstn->dfltTZ);
        pMsg->msgFlags = NEEDS_PARSING | PARSE_HOSTNAME | NEEDS_DNSRESOL;
        if (*pbIsPermitted == 2) {
            pMsg->msgFlags |= NEEDS_ACLCHK_U; /* request ACL check after resolution */
        }
        if (runModConf->bPreserveCase) {
            pMsg->msgFlags |= PRESERVE_CASE; /* preserve case of fromhost */
        }
        CHKiRet(msgSetFromSockinfoLen(pMsg, frominet, socklen));
        CHKiRet(ratelimitAddMsg(lstn->ratelimiter, multiSub, pMsg));
        STATSCOUNTER_INC(lstn->ctrSubmit, lstn->mutCtrSubmit);

             * rgerhards, 2009-11-16
             */
            if (lstn->bUseLegacyAllowedSender) {
                *pbIsPermitted = net.isAllowedSender2((uchar *)"UDP", (struct sockaddr *)frominet, "", 0);
            } else {
                *pbIsPermitted = net.isAllowedSenderList(lstn->pAllowedSenderRoot, (struct sockaddr *)frominet, "", 0);
            }

            if (*pbIsPermitted == 0) {
                DBGPRINTF("msg is not from an allowed sender\n");
                STATSCOUNTER_INC(lstn->ctrDisallowed, lstn->mutCtrDisallowed);
                if (glbl.GetOptionDisallowWarning(runModConf->pConf)) {
                    LogError(0, NO_ERRCODE, "imudp: UDP message from disallowed sender discarded");
                }
            }
        }
    } else {
        *pbIsPermitted = 1; /* no check -> everything permitted */
    }

    DBGPRINTF("recv(%d,%d),acl:%d,msg:%.*s\n", lstn->sock, (int)lenRcvBuf, *pbIsPermitted, (int)lenRcvBuf, rcvBuf);

    if (*pbIsPermitted != 0) {
        /* we now create our own message object and submit it to the queue */
        CHKiRet(msgConstructWithTime(&pMsg, stTime, ttGenTime));
        MsgSetRawMsg(pMsg, (char *)rcvBuf, lenRcvBuf);
        MsgSetInputName(pMsg, lstn->pInputName);
        MsgSetRuleset(pMsg, lstn->pRuleset);
        MsgSetFlowControlType(pMsg, eFLOWCTL_NO_DELAY);
        if (lstn->dfltTZ != NULL) MsgSetDfltTZ(pMsg, (char *)lstn->dfltTZ);
        pMsg->msgFlags = NEEDS_PARSING | PARSE_HOSTNAME | NEEDS_DNSRESOL;
        if (*pbIsPermitted == 2) {
            pMsg->msgFlags |= NEEDS_ACLCHK_U; /* request ACL check after resolution */
        }
        if (runModConf->bPreserveCase) {
            pMsg->msgFlags |= PRESERVE_CASE; /* preserve case of fromhost */
        }
        CHKiRet(msgSetFromSockinfoLen(pMsg, frominet, socklen));
        CHKiRet(ratelimitAddMsg(lstn->ratelimiter, multiSub, pMsg));
        STATSCOUNTER_INC(lstn->ctrSubmit, lstn->mutCtrSubmit);
    }

finalize_it:
    if (iRet != RS_RET_OK) {
        if (pMsg != NULL && iRet != RS_RET_DISCARDMSG) {
            msgDestruct(&pMsg);
        }
    }

    RETiRet;
}


