static rsRetVal createListner(es_str_t *port, struct cnfparamvals *pvals) {
    instanceConf_t *inst;
    int i;
    int bAppendPortUsed = 0;
    DEFiRet;

    CHKiRet(createInstance(&inst));
    CHKmalloc(inst->pszBindPort = (uchar *)es_str2cstr(port, NULL));
    for (i = 0; i < inppblk.nParams; ++i) {
        if (!pvals[i].bUsed) continue;
        if (!strcmp(inppblk.descr[i].name, "port")) {
            continue; /* array, handled by caller */
        } else if (!strcmp(inppblk.descr[i].name, "listenportfilename")) {
            CHKmalloc(inst->pszLstnPortFileName = (uchar *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "name")) {
            if (inst->inputname != NULL) {
                LogError(0, RS_RET_INVALID_PARAMS,
                         "imudp: name and inputname "
                         "parameter specified - only one can be used");

        } else if (!strcmp(inppblk.descr[i].name, "listenportfilename")) {
            CHKmalloc(inst->pszLstnPortFileName = (uchar *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "name")) {
            if (inst->inputname != NULL) {
                LogError(0, RS_RET_INVALID_PARAMS,
                         "imudp: name and inputname "
                         "parameter specified - only one can be used");
                ABORT_FINALIZE(RS_RET_INVALID_PARAMS);
            }
            CHKmalloc(inst->inputname = (uchar *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "name.appendport")) {
            if (bAppendPortUsed) {
                LogError(0, RS_RET_INVALID_PARAMS,
                         "imudp: name.appendport and "
                         "inputname.appendport parameter specified - only one can be used");
                ABORT_FINALIZE(RS_RET_INVALID_PARAMS);
            }
            inst->bAppendPortToInpname = (int)pvals[i].val.d.n;
            bAppendPortUsed = 1;
        } else if (!strcmp(inppblk.descr[i].name, "inputname")) {
            LogError(0, RS_RET_DEPRECATED,
                     "imudp: deprecated parameter inputname "
                     "used. Suggest to use name instead");
            if (inst->inputname != NULL) {
                LogError(0, RS_RET_INVALID_PARAMS,
                         "imudp: name and inputname "
                         "parameter specified - only one can be used");
                ABORT_FINALIZE(RS_RET_INVALID_PARAMS);
            }
            CHKmalloc(inst->inputname = (uchar *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "inputname.appendport")) {
            LogError(0, RS_RET_DEPRECATED,
                     "imudp: deprecated parameter inputname.appendport "
                     "used. Suggest to use name.appendport instead");
            if (bAppendPortUsed) {
                LogError(0, RS_RET_INVALID_PARAMS,
                         "imudp: name.appendport and "
                         "inputname.appendport parameter specified - only one can be used");
                ABORT_FINALIZE(RS_RET_INVALID_PARAMS);
            }
            bAppendPortUsed = 1;
            inst->bAppendPortToInpname = (int)pvals[i].val.d.n;
        } else if (!strcmp(inppblk.descr[i].name, "defaulttz")) {
            CHKmalloc(inst->dfltTZ = (uchar *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "address")) {
            CHKmalloc(inst->pszBindAddr = (uchar *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "device")) {
            CHKmalloc(inst->pszBindDevice = (char *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "ruleset")) {
            CHKmalloc(inst->pszBindRuleset = (uchar *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "ratelimit.burst")) {
            inst->ratelimitBurst = (int)pvals[i].val.d.n;
        } else if (!strcmp(inppblk.descr[i].name, "ratelimit.interval")) {
            inst->ratelimitInterval = (int)pvals[i].val.d.n;
        } else if (!strcmp(inppblk.descr[i].name, "ratelimit.name")) {
            CHKmalloc(inst->pszRatelimitName = (uchar *)es_str2cstr(pvals[i].val.d.estr, NULL));
        } else if (!strcmp(inppblk.descr[i].name, "rcvbufsize")) {
            const uint64_t val = pvals[i].val.d.n;
            if (val > 1024 * 1024 * 1024) {
                LogError(0, RS_RET_MISSING_CNFPARAMS,
                         "imudp: rcvbufsize maximum is 1 GiB, using "
                         "default instead");
            } else {
                inst->rcvbuf = (int)val;
            }
        } else if (!strcmp(inppblk.descr[i].name, "ipfreebind")) {
            inst->ipfreebind = (int)pvals[i].val.d.n;
        } else if (!strcmp(inppblk.descr[i].name, "allowedsender")) {
            if (pvals[i].val.d.ar == NULL || pvals[i].val.d.ar->nmemb == 0) {
                LogError(0, RS_RET_INVALID_PARAMS, "imudp: allowedSender array must not be empty");
                ABORT_FINALIZE(RS_RET_INVALID_PARAMS);
            }
            inst->bAllowedSendersSet = 1;
            for (int j = 0; j < pvals[i].val.d.ar->nmemb; ++j) {
                uchar *sender = (uchar *)es_str2cstr(pvals[i].val.d.ar->arr[j], NULL);
                CHKmalloc(sender);
                const rsRetVal entryRet =
                    net.addAllowedSenderEntry(&inst->pAllowedSendersRoot, &inst->pAllowedSendersLast, sender);
                free(sender);
                CHKiRet(entryRet);
            }
        } else {
            dbgprintf(
                "imudp: program error, non-handled "
                "param '%s'\n",
                inppblk.descr[i].name);
        }
    }

    /* check for mutual exclusivity and apply defaults */
    if (inst->pszRatelimitName != NULL) {
        if (inst->ratelimitInterval != -1 || inst->ratelimitBurst != -1) {
            LogError(0, RS_RET_INVALID_PARAMS,
                     "imudp: ratelimit.name is mutually exclusive with "
                     "ratelimit.interval and ratelimit.burst - using ratelimit.name");
        }
        /* ensure defaults are set to "off" values that won't interfere,
         * though they should be ignored by logic using the name.
         */
        inst->ratelimitInterval = 0;
        inst->ratelimitBurst = 0;
    } else {
        if (inst->ratelimitInterval == -1) inst->ratelimitInterval = DFLT_ratelimitInterval;
        if (inst->ratelimitBurst == -1) inst->ratelimitBurst = DFLT_ratelimitBurst;
    }
finalize_it:
    RETiRet;
}


